From e40872fc538f3216fd4d00aa969785b999a357bf Mon Sep 17 00:00:00 2001
From: Dave Reisner <dreisner@archlinux.org>
Date: Thu, 18 Dec 2014 18:10:46 -0500
Subject: [PATCH] path-util: fix breakage in path_is_mount_point

This fixes 2 problems introduced by 6feeeab0bc:

1) If name_to_handle_at returns ENOSYS for the child, we'll wrongly
return -ENOSYS when it returns the same for the parent. Immediately
jump to the fallback logic when we get ENOSYS.

2) If name_to_handle_at returns EOPNOTSUPP for the child but suceeds
for the parent, we'll be comparing an uninitialized value (mount_id) to
an initialized value (mount_id_parent). Initialize the mount_id
variables to invalid mount_ids to avoid this.

diff --git a/src/shared/path-util.c b/src/shared/path-util.c
index 8c43d060fb..ad9dc882b2 100644
--- a/src/shared/path-util.c
+++ b/src/shared/path-util.c
@@ -458,7 +458,7 @@ int path_is_mount_point(const char *t, bool allow_symlink) {
                 .handle.handle_bytes = MAX_HANDLE_SZ
         };

-        int mount_id, mount_id_parent;
+        int mount_id = -1, mount_id_parent = -1;
         _cleanup_free_ char *parent = NULL;
         struct stat a, b;
         int r;
@@ -473,7 +473,11 @@ int path_is_mount_point(const char *t, bool allow_symlink) {

         r = name_to_handle_at(AT_FDCWD, t, &h.handle, &mount_id, allow_symlink ? AT_SYMLINK_FOLLOW : 0);
         if (r < 0) {
-                if (IN_SET(errno, ENOSYS, EOPNOTSUPP))
+                if (errno == ENOSYS)
+                        /* This kernel does not support name_to_handle_at()
+                         * fall back to the traditional stat() logic. */
+                        goto fallback;
+                else if (errno == EOPNOTSUPP)
                         /* This kernel or file system does not support
                          * name_to_handle_at(), hence fallback to the
                          * traditional stat() logic */
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by improper handling of error codes returned by the `name_to_handle_at` function. Specifically, if the function returned `ENOSYS` for a child, the code incorrectly propagated this error for the parent without falling back to traditional logic. Additionally, if `name_to_handle_at` returned `EOPNOTSUPP` for the child but succeeded for the parent, the comparison involved uninitialized variables, leading to undefined behavior.

        Commit message:
        path-util: fix breakage in path_is_mount_point

This fixes 2 problems introduced by 6feeeab0bc:

1) If name_to_handle_at returns ENOSYS for the child, we'll wrongly
return -ENOSYS when it returns the same for the parent. Immediately
jump to the fallback logic when we get ENOSYS.

2) If name_to_handle_at returns EOPNOTSUPP for the child but suceeds
for the parent, we'll be comparing an uninitialized value (mount_id) to
an initialized value (mount_id_parent). Initialize the mount_id
variables to invalid mount_ids to avoid this.  

        Patch:

 int path_is_mount_point(const char *t, bool allow_symlink) {

         union file_handle_union h = {
                 .handle.handle_bytes = MAX_HANDLE_SZ
         };

-        int mount_id, mount_id_parent;
+        int mount_id = -1, mount_id_parent = -1;
         _cleanup_free_ char *parent = NULL;
         struct stat a, b;
         int r;
         bool nosupp = false;

         /* We are not actually interested in the file handles, but
          * name_to_handle_at() also passes us the mount ID, hence use
          * it but throw the handle away */

         if (path_equal(t, "/"))
                 return 1;

         r = name_to_handle_at(AT_FDCWD, t, &h.handle, &mount_id, allow_symlink ? AT_SYMLINK_FOLLOW : 0);
         if (r < 0) {
-                if (IN_SET(errno, ENOSYS, EOPNOTSUPP))
+                if (errno == ENOSYS)
+                        /* This kernel does not support name_to_handle_at()
+                         * fall back to the traditional stat() logic. */
+                        goto fallback;
+                else if (errno == EOPNOTSUPP)
                         /* This kernel or file system does not support
                          * name_to_handle_at(), hence fallback to the
                          * traditional stat() logic */
                         nosupp = true;
                 else if (errno == ENOENT)
                         return 0;
                 else
                         return -errno;
         }

         r = path_get_parent(t, &parent);
         if (r < 0)
                 return r;

         h.handle.handle_bytes = MAX_HANDLE_SZ;
         r = name_to_handle_at(AT_FDCWD, parent, &h.handle, &mount_id_parent, AT_SYMLINK_FOLLOW);
         if (r < 0)
                 if (errno == EOPNOTSUPP)
                         if (nosupp)
                                 /* Neither parent nor child do name_to_handle_at()?
                                    We have no choice but to fall back. */
                                 goto fallback;
                         else
                                 /* The parent can't do name_to_handle_at() but
                                  * the directory we are interested in can?
                                  * Or the other way around?
                                  * If so, it must be a mount point. */
                                 return 1;
                 else
                         return -errno;
         else
                 return mount_id != mount_id_parent;

 fallback:
         if (allow_symlink)
                 r = stat(t, &a);
         else
                 r = lstat(t, &a);

         if (r < 0) {
                 if (errno == ENOENT)
                         return 0;

                 return -errno;
         }

         r = path_get_parent(t, &parent);
         if (r < 0)
                 return r;

         r = stat(parent, &b);
         if (r < 0)
                 return -errno;

         return a.st_dev != b.st_dev;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```c
-        int mount_id, mount_id_parent;
+        int mount_id = -1, mount_id_parent = -1;

-                if (IN_SET(errno, ENOSYS, EOPNOTSUPP))
+                if (errno == ENOSYS)
+                        /* This kernel does not support name_to_handle_at()
+                         * fall back to the traditional stat() logic. */
+                        goto fallback;
+                else if (errno == EOPNOTSUPP)

-                if (errno == EOPNOTSUPP)
+                        if (nosupp)
                                 /* Neither parent nor child do name_to_handle_at()?
                                    We have no choice but to fall back. */
                                 goto fallback;
```
